                            Core.AroonValue uq = sQ.Update(fz_h[t], fz_l[t]);
                            sink += uq.AroonDown;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
