                    } catch (ArgumentException) { ufillOk = false; }
                }
            }
            {
                int p0 = lb + 1 + seedShift;
                if (p0 <= svN - 1) {
                    try {
                        Core.CdlonneckStream sA = c2.CdlonneckOpen(fz_o[..p0], fz_h[..p0], fz_l[..p0], fz_c[..p0]);
