                Core.CdlstalledpatternStream _fh = c2.CdlstalledpatternOpenAndFill(fz_o, fz_h, fz_l, fz_c, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
