        double[] fz_v = new double[svN];
        double[] fz_oi = new double[svN];
        FuzzData.FuzzGen(svShape, svSeed, svN, fz_o, fz_h, fz_l, fz_c, fz_v, fz_oi);
        int[] b0 = new int[svN];
        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        long peekReps = 0;
        bool peekRepAll = true;
        int fillChecked = 0;
        bool fillOk = true;
