                            if (SvBne(uA.Quadrature, uB.Quadrature) || SvXtierNe(uA.Quadrature, b1[t - beg], ref zsign)) { allOk = false; if (diag.Length == 0) diag = ",\"copyDiverged\":" + t; }
                        }
