        }
        int optInFastPeriod = GetInt(req, "optInFastPeriod", 12);
        int optInSlowPeriod = GetInt(req, "optInSlowPeriod", 26);
        int optInSignalPeriod = GetInt(req, "optInSignalPeriod", 9);
