                catch (ArgumentException) { /* expected: output 0 aliases input inReal */ }
                try { _ = c2.MacdOpenAndFill(fz_c, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, fz_c, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases input inReal */ }
                try { _ = c2.MacdOpenAndFill(fz_c, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, f1, fz_c); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases input inReal */ }
                try { _ = c2.MacdOpenAndFill(fz_c, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, f0, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 aliases output 0 */ }
                try { _ = c2.MacdOpenAndFill(fz_c, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, f1, f0); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 aliases output 0 */ }
