                catch (ArgumentException) { /* expected: outputs 1/2 partially overlap (offset) */ }
                try { _ = c2.MacdOpenAndFill(fz_c, optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, ovD.AsSpan(0, svN), ovD.AsSpan(0, svN + 1)); fillOk = false; }
                catch (ArgumentException) { /* expected: outputs 1/2 partially overlap (same start, longer) */ }
                try { _ = c2.MacdOpenAndFill(ovIn.AsSpan(0, svN), optInFastPeriod, optInSlowPeriod, optInSignalPeriod, ovIn.AsSpan(1, svN), f1, f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 0 partially overlaps an input */ }
                try { _ = c2.MacdOpenAndFill(ovIn.AsSpan(0, svN), optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, ovIn.AsSpan(1, svN), f2); fillOk = false; }
                catch (ArgumentException) { /* expected: output 1 partially overlaps an input */ }
                try { _ = c2.MacdOpenAndFill(ovIn.AsSpan(0, svN), optInFastPeriod, optInSlowPeriod, optInSignalPeriod, f0, f1, ovIn.AsSpan(1, svN)); fillOk = false; }
                catch (ArgumentException) { /* expected: output 2 partially overlaps an input */ }
            } catch (ArgumentException) { fillOk = false; }
            int seedShift = 0;
            int[] pcs = { lb + 1 + seedShift, lb + 13, svN / 2, svN - 1 };
            Array.Sort(pcs);
            int prevP = -1;
            for (int pi = 0; pi < pcs.Length; pi++) {
                int p = pcs[pi];
