        long legs = 0;
        bool allOk = true;
        bool peekAll = true;
        long peekReps = 0;
        bool peekRepAll = true;
        int fillChecked = 0;
        bool fillOk = true;
        int beg = 0, nb = 0;
        string diag = "";
        int rangeChecked = 0;
        bool rangeOk = true;
        long rangeLegs = 0;
        int rangeSites = 0;
        int ufillChecked = 0;
        bool ufillOk = true;
        long zsign = 0;
        long updAlloc = 0;
        Core c0 = new Core();
        if (!Enum.IsDefined(optInMAType)) {
            bool eOpen, eFill;
            try { _ = c0.MavpOpen(fz_c, fz_v, optInMinPeriod, optInMaxPeriod, optInMAType); eOpen = false; }
            catch (ArgumentException) { eOpen = true; }
            double[] f0 = new double[svN];
            Array.Fill(f0, (double)-1.2345678901234e300);
            try { _ = c0.MavpOpenAndFill(fz_c, fz_v, optInMinPeriod, optInMaxPeriod, optInMAType, f0); eFill = false; }
            catch (ArgumentException) { eFill = true; }
            bool eOk = eOpen && eFill;
            return "{\"retCode\":2,\"legs\":0,\"nb\":0,\"openRejects\":" + (eOk ? 1 : 0) + ",\"enumRejects\":" + ((eOpen ? 1 : 0) + (eFill ? 1 : 0)) + ",\"ok\":" + (eOk ? 1 : 0) + ",\"peek_ok\":1}";
        }
        int rounds = 1;
        for (int rd = 0; rd < rounds; rd++) {
            CoreBuilder cb = Core.Builder();
            cb = cb.UnstablePeriod((FuncUnstId)23, svK);
            cb = cb.UnstablePeriod((FuncUnstId)14, svK);
            cb = cb.UnstablePeriod((FuncUnstId)13, svK);
            cb = cb.UnstablePeriod((FuncUnstId)5, svK);
            Core c2;
            try { c2 = cb.Build(); }
            catch (ArgumentOutOfRangeException) {
                return "{\"error\":\"unstablePeriod out of range\"}";
            }
            RetCode rc;
            try { rc = c2.MAVP_Impl(0, svN - 1, fz_c, fz_v, optInMinPeriod, optInMaxPeriod, optInMAType, out beg, out nb, b0); }
            catch (Exception _sve) when (_sve is ITaLibFailure) { rc = ((ITaLibFailure)_sve).RetCode; beg = 0; nb = 0; }
            int lb = c2.MAVP_Lookback(optInMinPeriod, optInMaxPeriod, optInMAType);
            if (rc != RetCode.Success || nb == 0) {
                bool openRejects;
