                prevP = p;
                Core.MavpStream st;
                try { st = c2.MavpOpen(fz_c[..p], fz_v[..p], optInMinPeriod, optInMaxPeriod, optInMAType); }
                catch (ArgumentException) { allOk = false; if (diag.Length == 0) diag = ",\"openRejectP\":" + p; continue; }
                legs++;
