                    try {
                        Core.MavpStream sQ = c2.MavpOpen(fz_c[..pa], fz_v[..pa], optInMinPeriod, optInMaxPeriod, optInMAType);
                        double sink = 0.0;
                        long a0 = GC.GetAllocatedBytesForCurrentThread();
                        for (int t = pa; t < svN; t++) {
                            double uq = sQ.Update(fz_c[t], fz_v[t]);
                            sink += uq;
                        }
                        long ad = GC.GetAllocatedBytesForCurrentThread() - a0;
                        svUpdSink += sink;
                        if (ad > updAlloc) updAlloc = ad;
