                catch (ArgumentException) { /* expected: output 0 aliases input inLow */ }
                try { _ = c2.UltoscOpenAndFill(fz_h, fz_l, fz_c, optInTimePeriod1, optInTimePeriod2, optInTimePeriod3, fz_c); fillOk = false; }
