                Core.VwmaStream _fh = c2.VwmaOpenAndFill(fz_c, fz_v, optInTimePeriod, f0);
                OutRange _fr = _fh.OutRange;
                rangeChecked = 1; rangeLegs++; rangeSites |= 1;
